$('#netZoomIn').addEventListener('click',()=>changeNetZoom(.16));$('#netZoomOut').addEventListener('click',()=>changeNetZoom(-.16));$('#netRotateLeft').addEventListener('click',()=>{netView.rotation-=15;applyNetView()});$('#netRotateRight').addEventListener('click',()=>{netView.rotation+=15;applyNetView()});$('#netReset').addEventListener('click',()=>{resetNetView();$('#foldStatus').textContent='Vista del desarrollo restablecida'});
const netSvg=$('#netSvg'),netPointers=new Map();let netDrag=null,netMoved=false,netPinch=null;
netSvg.addEventListener('pointerdown',e=>{if(foldingNet.progress>.015)return;netSvg.setPointerCapture(e.pointerId);netPointers.set(e.pointerId,{x:e.clientX,y:e.clientY});netMoved=false;if(netPointers.size===1)netDrag={x:e.clientX,y:e.clientY,startX:netView.x,startY:netView.y};if(netPointers.size===2){const p=[...netPointers.values()];netPinch={distance:Math.hypot(p[1].x-p[0].x,p[1].y-p[0].y),scale:netView.scale}}});
netSvg.addEventListener('pointermove',e=>{if(!netPointers.has(e.pointerId))return;netPointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(netDrag&&Math.hypot(e.clientX-netDrag.x,e.clientY-netDrag.y)>4)netMoved=true;if(netPointers.size===2&&netPinch){netMoved=true;const p=[...netPointers.values()],distance=Math.hypot(p[1].x-p[0].x,p[1].y-p[0].y);netView.scale=Math.max(.65,Math.min(2.8,netPinch.scale*distance/netPinch.distance));applyNetView()}else if(netDrag&&netMoved){const rect=netSvg.getBoundingClientRect();netView.x=netDrag.startX+(e.clientX-netDrag.x)*520/rect.width;netView.y=netDrag.startY+(e.clientY-netDrag.y)*320/rect.height;applyNetView()}});
const endNetPointer=e=>{netPointers.delete(e.pointerId);if(!netPointers.size){netDrag=null;netPinch=null}};netSvg.addEventListener('pointerup',endNetPointer);netSvg.addEventListener('pointercancel',endNetPointer);
netSvg.addEventListener('wheel',e=>{if(foldingNet.progress>.015)return;e.preventDefault();changeNetZoom(e.deltaY<0?.12:-.12)},{passive:false});
netSvg.addEventListener('click',e=>{if(netMoved||foldingNet.progress>.015)return;$$('#netSvg .selected').forEach(x=>x.classList.remove('selected'));const target=e.target.closest('[data-face],[data-vertex],[data-edge]');if(!target)return;target.classList.add('selected');const d=solids[currentKey];if(target.dataset.face)$('#foldStatus').textContent=`Cara ${target.dataset.face} de ${d.faces}: ${d.face.toLowerCase()}.`;else if(target.dataset.vertex)$('#foldStatus').textContent=`Punto de la plantilla: al plegar, coincide con uno de los ${d.vertices} vértices.`;else $('#foldStatus').textContent=`Arista señalada: una de las ${d.edges} aristas del sólido al plegarse.`});
