$('#downloadSvg').addEventListener('click',()=>{const svg=$('#workshopSvg').cloneNode(true);svg.setAttribute('xmlns','http://www.w3.org/2000/svg');const d=solids[currentKey];const blob=new Blob([`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 520 320"><style>.net-face{fill:#eeeaff;stroke:none}.face-1{fill:#dff7f2}.face-2{fill:#ffe8f2}.face-3{fill:#fff1c9}.face-4{fill:#dcecff}.glue-tab{fill:#fff;stroke:#8077d9;stroke-width:1.2;stroke-dasharray:4 3}.cut-edge{stroke:#332d6b;stroke-width:2;fill:none}.fold-edge{stroke:#786fbe;stroke-width:1.4;stroke-dasharray:6 5;fill:none}.dimension-text{font:700 13px Arial;fill:#332d6b}</style><text x="20" y="28" font-family="Arial" font-size="16" font-weight="bold">Red plana: ${d.name}</text>${svg.innerHTML}</svg>`],{type:'image/svg+xml'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`red-${d.name.toLowerCase().replaceAll(' ','-')}.svg`;a.click();URL.revokeObjectURL(a.href);showToast('Red SVG descargada')});$('#printNet').addEventListener('click',()=>window.print());
